mapper.insert:
INSERT INTO `mission_progress` (
user_id
, mission_id
, current_count
, progress
, status
) VALUES (
#{userId}
, #{missionId}
, 0
, 0
, 'IN_PROGRESS'
)

mapper.update:
UPDATE `mission_progress`
SET current_count = #{currentCount}
, progress = #{progress}
, status = #{status}
, updated_at = CURRENT_TIMESTAMP(6)
WHERE id = #{userMissionId}
AND status <> 'DONE'

UPDATE `mission_progress`
SET status = #{status}
, updated_at = CURRENT_TIMESTAMP(6)
WHERE id = #{userMissionId}

mapper.insert:
INSERT INTO `point_history`
(
user_id
, mission_id
, point
, reason
)
VALUES
(
#{userId}
, #{missionId}
, #{rewardPoint}
, #{reason}
)

INSERT INTO `mission_create`
(
title
, description
, mission_type
, trigger_event
, target_count
, reward_point
, auto_complete
, start_at
, end_at
)
VALUES
(
#{title}
, #{description}
, #{missionType}
, #{triggerEvent}
, #{targetCount}
, #{rewardPoint}
, #{autoComplete}
, #{startAt}
, #{endAt}
)

INSERT INTO `mission_create_history` (
mission_id, title, description, mission_type,
trigger_event, target_count, reward_point,
auto_complete, start_at, end_at
) VALUES (
#{id}, #{title}, #{description}, #{missionType},
#{triggerEvent}, #{targetCount}, #{rewardPoint},
#{autoComplete}, #{startAt}, #{endAt}
)
